(function(){const t=14,n=240,a=160;let o=0,r=0;const e=new Float32Array(t),s=new Float32Array(t);return{init:function(n){o=n,r=0;for(let n=0;n<t;n++)e[n]=Math.randInt(628)/100,s[n]=Math.randInt(300)},draw:function(h){"ram";h.setColor(3);const c=3+3*o;for(let o=0;o<t;o++){const t=Math.cos(e[o]),i=Math.sin(e[o]),l=s[o],M=Math.max(l-(6+l/12),0);r>0&&(h.setColor(0),h.drawLine(n+t*l|0,a+i*l|0,n+t*M|0,a+i*M|0),h.setColor(3));let d=l+c*(1+l/90);d>340&&(d=4,e[o]=Math.randInt(628)/100),s[o]=d;const f=Math.cos(e[o]),w=Math.sin(e[o]),u=Math.max(d-(6+d/12),0);h.drawLine(n+f*d|0,a+w*d|0,n+f*u|0,a+w*u|0)}r++}}});